/** Régions jouables dans la build publiée (itch.io). Étendre pour ouvrir Paldea. */
export const RELEASED_REGION_IDS = ['kanto', 'johto', 'hoenn', 'sinnoh', 'unova','kalos'] as const;

export function isRegionReleased(regionId: string): boolean {
    return (RELEASED_REGION_IDS as readonly string[]).includes(String(regionId || ''));
}
